mapper.select:
SELECT o.id AS orderId, o.order_no AS orderNo, m.name AS movieName, m.poster_url AS posterUrl, h.name AS hallName, h.location, s.start_time AS startTime, o.total_price AS totalPrice, o.status, o.create_time AS createTime FROM `order` o JOIN order_item oi ON oi.order_id = o.id JOIN session s ON s.id = oi.session_id JOIN movie m ON m.id = s.movie_id JOIN hall h ON h.id = s.hall_id WHERE o.user_id = #{userId}
AND m.name LIKE CONCAT('%', #{movieName}, '%')
AND o.status = #{status}
GROUP BY o.id, o.order_no, m.name, m.poster_url, h.name, h.location, s.start_time, o.total_price, o.status, o.create_time ORDER BY o.create_time DESC;
